```java
// Secure code: Proper use of the Java API with input validation, secure practices, and synchronization.
import java.util.Date;
import java.text.SimpleDateFormat;
import java.util.concurrent.locks.ReentrantLock;

public class GoodExample {
    private static final SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
    private static final ReentrantLock lock = new ReentrantLock();

    public static void main(String[] args) {
        // Secure: Use proper input validation to prevent injection and XSS attacks.
        String userInput = "<script>alert('XSS');</script>";
        if (isValidInput(userInput)) {
            System.out.println("Valid input: " + userInput);
        } else {
            System.out.println("Invalid input detected.");
        }

        // Secure: Use synchronized resource when needed for thread safety.
        lock.lock();
        try {
            System.out.println("Date: " + sdf.format(new Date()));
        } finally {
            lock.unlock();
        }
    }

    private static boolean isValidInput(String input) {
        // Simple validation example; real-world scenarios require more robust checks.
        return input != null && !input.trim().isEmpty() && !input.contains("<") && !input.contains(">");
    }
}
