***
[code snippet 2]  
```java
// अच्छा कोड: PreparedStatement का उपयोग करके SQL Injection को रोकना
public String getUserPassword(String username) {
    String query = "SELECT password FROM users WHERE username = ?";
    try (PreparedStatement preparedStatement = connection.prepareStatement(query)) {
        preparedStatement.setString(1, username);
        ResultSet resultSet = preparedStatement.executeQuery();
        if (resultSet.next()) {
            return resultSet.getString("password");
        }
    } catch (SQLException e) {
        e.printStackTrace();
    }
    return null;
}
// इस कोड में PreparedStatement का उपयोग करके डेटा को सुरक्षित तरीके से जोड़ा जाता है।
// यह SQL Injection के खतरों को रोकता है और एक सुरक्षित तरीका है।
```

