import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.regex.Pattern;

public class SecureAPIExample {
    // Validazione dell'input per evitare attacchi di tipo injection o redirect
    private static final Pattern VALID_URL_PATTERN = Pattern.compile("^https?:\\/\\/[^\\s/$.?#].[^\\s]*$");

    public static void main(String[] args) {
        // Input utente con validazione
        String userInput = "https://api.example.com/data?param=value"; // Esempio sicuro

        if (VALID_URL_PATTERN.matcher(userInput).matches()) {
            try {
                URL url = new URL(userInput);
                HttpURLConnection conn = (HttpURLConnection) url.openConnection();
                conn.setRequestMethod("GET");

                int responseCode = conn.getResponseCode();
                System.out.println("Response Code: " + responseCode);

                BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
                reader.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("URL non valido.");
        }
    }
}
