// Corretto: Utilizzo sicuro della API Java con validazione e gestione delle eccezioni
public class SecureServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String input = request.getParameter("input");
        // Validazione dell'input prima dell'utilizzo
        if (input != null && !input.trim().isEmpty() && isSafeInput(input)) {
            // Esecuzione di operazioni sicure basate sull'input
            processInput(input);
        } else {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Input non valido.");
        }
    }

    private boolean isSafeInput(String input) {
        // Esempio semplice di validazione: permette solo caratteri alfanumerici e spazi
        return input.matches("^[a-zA-Z0-9\\s]*$");
    }

    private void processInput(String input) {
        // Logica sicura per elaborare l'input
        System.out.println("Input ricevuto: " + input);
    }
}
